precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_grain_amount, u_warmth, u_contrast, u_saturation;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec4 color = texture2D(u_texture, v_texCoord);

  // Film grain
  float grain = (random(v_texCoord + u_time) - 0.5) * u_grain_amount;
  color.rgb += grain;

  // Warmth adjustment
  color.r += u_warmth * 0.1;
  color.b -= u_warmth * 0.05;

  // Contrast
  color.rgb = (color.rgb - 0.5) * u_contrast + 0.5;

  // Saturation
  float gray = dot(color.rgb, vec3(0.299, 0.587, 0.114));
  color.rgb = mix(vec3(gray), color.rgb, u_saturation);

  // Film curve
  color.rgb = pow(color.rgb, vec3(0.9));

  gl_FragColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_neon_intensity, u_glitch_amount, u_scan_lines, u_chromatic_aberration;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec2 uv = v_texCoord;

  // Glitch effect
  float glitch = random(vec2(floor(uv.y * 100.0), floor(u_time * 10.0)));
  if (glitch > 0.95 && u_glitch_amount > 0.0) {
    uv.x += (random(vec2(u_time)) - 0.5) * u_glitch_amount * 0.1;
  }

  // Chromatic aberration
  vec4 color;
  color.r = texture2D(u_texture, uv + vec2(u_chromatic_aberration * 0.01, 0.0)).r;
  color.g = texture2D(u_texture, uv).g;
  color.b = texture2D(u_texture, uv - vec2(u_chromatic_aberration * 0.01, 0.0)).b;
  color.a = 1.0;

  // Neon enhancement
  vec3 neon = color.rgb;
  neon.r = pow(neon.r, 0.8);
  neon.g = pow(neon.g, 0.6);
  neon.b = pow(neon.b, 0.4);
  color.rgb = mix(color.rgb, neon, u_neon_intensity);

  // Scan lines
  float scanline = sin(uv.y * u_resolution.y * 2.0) * 0.1 * u_scan_lines;
  color.rgb += scanline;

  // Color grading
  color.rgb *= vec3(1.2, 0.9, 1.4); // Cyan-magenta tint

  gl_FragColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_brush_size, u_brush_intensity, u_color_reduction;
varying vec2 v_texCoord;

vec3 quantizeColor(vec3 color, float levels) {
  return floor(color * levels) / levels;
}

void main() {
  vec2 texelSize = 1.0 / u_resolution;
  vec4 color = texture2D(u_texture, v_texCoord);

  // Oil painting effect using median filter
  vec3 result = vec3(0.0);
  float totalWeight = 0.0;

  for (float x = -u_brush_size; x <= u_brush_size; x += 1.0) {
    for (float y = -u_brush_size; y <= u_brush_size; y += 1.0) {
      vec2 offset = vec2(x, y) * texelSize;
      vec3 sample = texture2D(u_texture, v_texCoord + offset).rgb;

      float distance = length(vec2(x, y));
      float weight = exp(-distance * distance / (u_brush_size * u_brush_size));

      result += sample * weight;
      totalWeight += weight;
    }
  }

  result /= totalWeight;

  // Color quantization
  float levels = mix(256.0, 8.0, u_color_reduction);
  result = quantizeColor(result, levels);

  // Mix with original
  result = mix(color.rgb, result, u_brush_intensity);

  gl_FragColor = vec4(result, color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_wetness, u_paper_texture, u_color_bleeding;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

void main() {
  vec2 texelSize = 1.0 / u_resolution;
  vec4 color = texture2D(u_texture, v_texCoord);

  // Color bleeding effect
  vec3 bleed = vec3(0.0);
  for (float x = -2.0; x <= 2.0; x += 1.0) {
    for (float y = -2.0; y <= 2.0; y += 1.0) {
      vec2 offset = vec2(x, y) * texelSize * u_color_bleeding;
      bleed += texture2D(u_texture, v_texCoord + offset).rgb;
    }
  }
  bleed /= 25.0;

  // Wet blending
  color.rgb = mix(color.rgb, bleed, u_wetness * 0.5);

  // Paper texture
  float noise = random(v_texCoord * 100.0);
  float paper = 1.0 - u_paper_texture * 0.3 * noise;
  color.rgb *= paper;

  // Watercolor transparency
  color.rgb = pow(color.rgb, vec3(1.2));

  // Soften edges
  float luminance = dot(color.rgb, vec3(0.299, 0.587, 0.114));
  color.a *= mix(0.7, 1.0, luminance);

  gl_FragColor = vec4(color.rgb, color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_line_intensity, u_hatching_density;
uniform vec3 u_paper_color;
varying vec2 v_texCoord;

void main() {
  vec2 texelSize = 1.0 / u_resolution;
  vec4 color = texture2D(u_texture, v_texCoord);

  // Convert to grayscale
  float gray = dot(color.rgb, vec3(0.299, 0.587, 0.114));

  // Edge detection (Sobel operator)
  float edge = 0.0;

  // Horizontal edges
  edge += texture2D(u_texture, v_texCoord + vec2(-texelSize.x, -texelSize.y)).r * -1.0;
  edge += texture2D(u_texture, v_texCoord + vec2(-texelSize.x, 0.0)).r * -2.0;
  edge += texture2D(u_texture, v_texCoord + vec2(-texelSize.x, texelSize.y)).r * -1.0;
  edge += texture2D(u_texture, v_texCoord + vec2(texelSize.x, -texelSize.y)).r * 1.0;
  edge += texture2D(u_texture, v_texCoord + vec2(texelSize.x, 0.0)).r * 2.0;
  edge += texture2D(u_texture, v_texCoord + vec2(texelSize.x, texelSize.y)).r * 1.0;

  // Vertical edges
  float edgeV = 0.0;
  edgeV += texture2D(u_texture, v_texCoord + vec2(-texelSize.x, -texelSize.y)).r * -1.0;
  edgeV += texture2D(u_texture, v_texCoord + vec2(0.0, -texelSize.y)).r * -2.0;
  edgeV += texture2D(u_texture, v_texCoord + vec2(texelSize.x, -texelSize.y)).r * -1.0;
  edgeV += texture2D(u_texture, v_texCoord + vec2(-texelSize.x, texelSize.y)).r * 1.0;
  edgeV += texture2D(u_texture, v_texCoord + vec2(0.0, texelSize.y)).r * 2.0;
  edgeV += texture2D(u_texture, v_texCoord + vec2(texelSize.x, texelSize.y)).r * 1.0;

  edge = sqrt(edge * edge + edgeV * edgeV);

  // Hatching pattern
  float hatch = 1.0;
  if (gray < 0.8) {
    float pattern = sin((v_texCoord.x + v_texCoord.y) * u_resolution.x * 0.5);
    hatch = mix(1.0, pattern * 0.5 + 0.5, u_hatching_density * (1.0 - gray));
  }

  // Combine edges and hatching
  float pencil = (1.0 - edge * u_line_intensity) * hatch;
  pencil = max(pencil, 1.0 - gray);

  // Apply paper color
  vec3 result = mix(vec3(0.0), u_paper_color, pencil);

  gl_FragColor = vec4(result, color.a);
}
